// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        // seed controls how many times the attacker re-enters; at least one entry is needed
        attacker.setAttempts(bound(seed % 5, 1, 5));
        try c.getFirstWithdrawalBonus(address(attacker)) {
            // the reward paid out must be exactly one bonus (100), never doubled by re-entry
            assertTrue(attacker.received() <= 100, "reentrancy allowed double payout");
        } catch {
            // reference may revert the outer call (lock); that is admissible
            assertTrue(true);
        }
    }
}

contract ReentrantAttacker {
    C public immutable c;
    uint256 public attempts;
    uint256 public received;

    constructor(C _c) { c = _c; }

    function setAttempts(uint256 n) external { attempts = n; }

    receive() external payable {
        received += msg.value;
        if (attempts > 0) {
            attempts--;
            try c.withdrawReward(address(this)) {} catch {}
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 funding) public {
        // wide admissible domain: the contract must be funded enough for the
        // credited reward plus any (re-entrant) extra payout the implementation allows
        funding = bound(funding, 200, type(uint256).max / 2);
        vm.deal(address(c), funding);

        // drive c through the bonus path; the attacker re-enters withdrawReward
        c.getFirstWithdrawalBonus(address(attacker));

        // Rule: total extracted per recipient never exceeds its credited reward (100)
        assertTrue(attacker.totalReceived() <= 100);
    }
}

contract Attacker {
    C target;
    uint public totalReceived;
    bool reentered;

    constructor(C t) {
        target = t;
    }

    receive() external payable {
        totalReceived += msg.value;
        if (!reentered) {
            reentered = true;
            target.withdrawReward(address(this));
        }
    }
}
